from __future__ import annotations

import dataclasses
from pathlib import Path
from types import ModuleType
from typing import Any, Dict, List, Optional, Union

from pydantic import BaseModel, ConfigDict, Field, model_validator

from rasa.core.a2a_server.config import (
    A2A_SERVER_KEY,
    A2AServerConfig,
    parse_a2a_server_config,
)
from rasa.core.constants import MCP_SERVERS_KEY
from rasa.shared.agents.auth.utils import validate_secrets_in_params
from rasa.shared.core.constants import (
    GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE,
    GLOBAL_SILENCE_TIMEOUT_KEY,
)
from rasa.shared.exceptions import RasaException
from rasa.utils.endpoints import (
    EndpointConfig,
    read_endpoint_config,
    read_property_config_from_endpoints_file,
)

RECORDING_PATH_PREFIX = "recordings/"


class MCPFromSlotsEntry(BaseModel):
    """One mapping from a slot to an _meta key (sent during MCP tool calls)."""

    slot: str = Field(
        ..., description="Slot name to read from (tracker or agent input)."
    )
    param: str = Field(..., description="Key in _meta sent to the MCP server.")

    @model_validator(mode="after")
    def validate_non_empty_strings(self) -> "MCPFromSlotsEntry":
        if not (self.slot and self.slot.strip()):
            raise ValueError("slot must be a non-empty string")
        if not (self.param and self.param.strip()):
            raise ValueError("param must be a non-empty string")
        return self


class MCPMetaMapConfig(BaseModel):
    """Configuration for injecting metadata into MCP tool call _meta parameter.

    Values are sent to the MCP server in the _meta field of tools/call requests
    and are not visible to the LLM. Use for user context, auth, or API versioning.

    - from_slots: runtime values from tracker/agent slots (keyed by param).
    - static: fixed key-value pairs always sent in _meta (e.g. api_version, source).
    """

    from_slots: Optional[List[MCPFromSlotsEntry]] = Field(
        default=None,
        description=(
            "List of {slot, param} mappings. Slot value is read from"
            "tracker/agent input and sent as _meta[param]."
        ),
    )
    static: Optional[Dict[str, str]] = Field(
        default=None,
        description=(
            "Fixed key-value pairs always sent in _meta (e.g. api_version, source)."
        ),
    )

    @model_validator(mode="after")
    def validate_static_non_empty_strings(self) -> "MCPMetaMapConfig":
        if not self.static:
            return self
        for key, value in self.static.items():
            if not isinstance(key, str) or not key.strip():
                raise ValueError("meta_map.static: keys must be non-empty strings")
            if not isinstance(value, str) or not value.strip():
                raise ValueError("meta_map.static: values must be non-empty strings")
        return self


@dataclasses.dataclass
class InteractionHandlingConfig:
    """Configuration for interaction handling."""

    global_silence_timeout: Union[float, int] = GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE

    def __post_init__(self) -> None:
        # Validate the type of `global_silence_timeout`.
        if isinstance(self.global_silence_timeout, str):
            try:
                self.global_silence_timeout = float(self.global_silence_timeout)
            except ValueError:
                raise RasaException(
                    f"Type for {GLOBAL_SILENCE_TIMEOUT_KEY} is wrong, expected number. "
                    f"Got: '{self.global_silence_timeout}'. "
                )

        if not isinstance(self.global_silence_timeout, (float, int)):
            raise RasaException(
                f"Type for {GLOBAL_SILENCE_TIMEOUT_KEY} is wrong, expected number. "
                f"Got: '{type(self.global_silence_timeout)}'. "
            )

        if self.global_silence_timeout <= 0:
            raise RasaException(
                f"Value for {GLOBAL_SILENCE_TIMEOUT_KEY} must be a positive number. "
                f"Got: '{self.global_silence_timeout}'. "
            )

    @classmethod
    def from_dict(cls, data: Optional[Dict[str, Any]]) -> InteractionHandlingConfig:
        """Create a InteractionHandlingConfig instance from a dictionary."""
        return cls(
            global_silence_timeout=data.get(
                GLOBAL_SILENCE_TIMEOUT_KEY, GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE
            )
            if data is not None
            else GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE
        )

    def to_dict(self) -> Dict[str, Any]:
        """Convert the interaction handling configuration to a dictionary."""
        return {
            GLOBAL_SILENCE_TIMEOUT_KEY: self.global_silence_timeout,
        }


class MCPServerConfig(BaseModel):
    model_config = ConfigDict(extra="allow")
    name: str = Field(..., description="The name of the MCP server.")
    url: str = Field(..., description="The URL of the MCP server.")
    type: str = Field(..., description="The type of the MCP server.")
    additional_params: Optional[Dict[str, Any]] = Field(
        default_factory=dict, description="Additional parameters for the MCP server."
    )
    meta_map: Optional[MCPMetaMapConfig] = Field(
        default=None,
        description="Optional mapping of slots to _meta sent with MCP tool calls.",
    )
    pre_call_hook: Optional[str] = Field(
        default=None,
        description=(
            "Optional dotted import path to a call-time credential hook invoked "
            "immediately before each MCP tool call on this server. Its returned "
            "OutboundCallResult metadata is merged into the MCP _meta."
        ),
    )

    @model_validator(mode="after")
    def validate_type(self) -> MCPServerConfig:
        # validate that type is "http"
        if self.type not in ["http", "https"]:
            raise ValueError(f"Invalid MCP server type: {self.type}")
        # validate that name and url are not empty
        if not self.name or not self.url:
            raise ValueError("Name and URL cannot be empty")
        # validate secrets in additional_params
        if self.additional_params:
            validate_secrets_in_params(
                self.additional_params, f"MCP server - '{self.name}'"
            )
        return self

    @model_validator(mode="before")
    def collect_additional_params(cls, values: Dict[str, Any]) -> Dict[str, Any]:
        base_fields = {"name", "url", "type", "meta_map", "pre_call_hook"}
        extras = {k: v for k, v in values.items() if k not in base_fields}
        if extras:
            values["additional_params"] = extras
            # remove them from top level so Pydantic doesn’t complain
            for k in extras:
                values.pop(k)
        return values


class RecordingS3Config(BaseModel):
    """S3 object storage settings for call recordings."""

    model_config = ConfigDict(extra="forbid")

    bucket: str
    region: Optional[str] = None
    prefix: str = RECORDING_PATH_PREFIX
    endpoint_url: Optional[str] = None


class RecordingGCSConfig(BaseModel):
    """Google Cloud Storage settings for call recordings."""

    model_config = ConfigDict(extra="forbid")

    bucket: str
    prefix: str = RECORDING_PATH_PREFIX


class RecordingAzureConfig(BaseModel):
    """Azure Blob Storage settings for call recordings."""

    model_config = ConfigDict(extra="forbid")

    container: str
    account_name: str
    prefix: str = RECORDING_PATH_PREFIX
    endpoint_url: Optional[str] = None


class RecordingLocalConfig(BaseModel):
    """Local filesystem settings for call recordings."""

    model_config = ConfigDict(extra="forbid")

    path: str


class RecordingConfig(BaseModel):
    """Configuration for call recordings.

    Unknown keys are rejected so a misspelled field is not dropped. ``provider``
    has no default and is required when recordings are enabled.
    """

    model_config = ConfigDict(extra="forbid")

    enabled: bool = False
    provider: Optional[str] = None
    s3: Optional[RecordingS3Config] = None
    gcs: Optional[RecordingGCSConfig] = None
    azure: Optional[RecordingAzureConfig] = None
    local: Optional[RecordingLocalConfig] = None

    def require_provider(self) -> str:
        """Return the storage provider.

        Raises:
            ValueError: ``provider`` was omitted.
        """
        if self.provider is None:
            raise ValueError(
                "recordings.provider is required when recordings are enabled. "
                "Supported providers: 's3', 'gcs', 'azure', 'local'."
            )
        return self.provider

    @model_validator(mode="after")
    def validate_provider_config(self) -> "RecordingConfig":
        if not self.enabled:
            return self
        provider = self.require_provider()
        if provider == "s3":
            if self.s3 is None:
                raise ValueError(
                    "recordings.s3 must be configured when provider is 's3'."
                )
            return self
        if provider == "gcs":
            if self.gcs is None:
                raise ValueError(
                    "recordings.gcs must be configured when provider is 'gcs'."
                )
            return self
        if provider == "azure":
            if self.azure is None:
                raise ValueError(
                    "recordings.azure must be configured when provider is 'azure'."
                )
            return self
        if provider == "local":
            if self.local is None:
                raise ValueError(
                    "recordings.local must be configured when provider is 'local'."
                )
            return self
        raise ValueError(
            "Unsupported recordings provider "
            f"'{provider}'. Supported providers: 's3', 'gcs', 'azure', 'local'."
        )


class AvailableEndpoints:
    """Collection of configured endpoints."""

    @classmethod
    def read_endpoints(cls, endpoint_file: Path) -> AvailableEndpoints:
        """Read the different endpoints from a yaml file."""
        nlg = read_endpoint_config(endpoint_file, endpoint_type="nlg")
        nlu = read_endpoint_config(endpoint_file, endpoint_type="nlu")
        action = read_endpoint_config(endpoint_file, endpoint_type="action_endpoint")
        model = read_endpoint_config(endpoint_file, endpoint_type="models")
        tracker_store = read_endpoint_config(
            endpoint_file, endpoint_type="tracker_store"
        )
        lock_store = read_endpoint_config(endpoint_file, endpoint_type="lock_store")
        event_broker = read_endpoint_config(endpoint_file, endpoint_type="event_broker")
        vector_store = read_endpoint_config(endpoint_file, endpoint_type="vector_store")
        timer_store = read_endpoint_config(endpoint_file, endpoint_type="timer_store")
        raw_mcp_servers = read_property_config_from_endpoints_file(
            endpoint_file, property_name=MCP_SERVERS_KEY
        )
        mcp_servers = (
            [MCPServerConfig(**server) for server in raw_mcp_servers]
            if raw_mcp_servers
            else None
        )
        model_groups = read_property_config_from_endpoints_file(
            endpoint_file, property_name="model_groups"
        )
        privacy = read_property_config_from_endpoints_file(
            endpoint_file, property_name="privacy"
        )
        raw_recordings = read_property_config_from_endpoints_file(
            endpoint_file, property_name="recordings"
        )
        recordings = RecordingConfig(**raw_recordings) if raw_recordings else None

        interaction_handling = InteractionHandlingConfig.from_dict(
            read_property_config_from_endpoints_file(
                endpoint_file, property_name="interaction_handling"
            )
        )
        a2a_server = parse_a2a_server_config(
            read_property_config_from_endpoints_file(
                endpoint_file, property_name=A2A_SERVER_KEY
            )
        )

        return cls(
            endpoint_file,
            nlg,
            nlu,
            action,
            model,
            tracker_store,
            lock_store,
            event_broker,
            vector_store,
            mcp_servers,
            model_groups,
            privacy,
            recordings,
            interaction_handling,
            timer_store,
            a2a_server,
        )

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> AvailableEndpoints:
        """Create endpoint settings from a spawn-safe dictionary."""

        def endpoint_config(key: str) -> Optional[EndpointConfig]:
            value = data.get(key)
            return EndpointConfig.from_dict(value) if value is not None else None

        raw_mcp_servers = data.get(MCP_SERVERS_KEY)
        mcp_servers = (
            [MCPServerConfig(**server) for server in raw_mcp_servers]
            if raw_mcp_servers
            else None
        )
        raw_recordings = data.get("recordings")
        raw_a2a_server = data.get(A2A_SERVER_KEY)
        return cls(
            nlg=endpoint_config("nlg"),
            nlu=endpoint_config("nlu"),
            action=endpoint_config("action_endpoint"),
            model=endpoint_config("models"),
            tracker_store=endpoint_config("tracker_store"),
            lock_store=endpoint_config("lock_store"),
            event_broker=endpoint_config("event_broker"),
            vector_store=endpoint_config("vector_store"),
            mcp_servers=mcp_servers,
            model_groups=data.get("model_groups"),
            privacy=data.get("privacy"),
            recordings=(
                RecordingConfig.model_validate(raw_recordings)
                if raw_recordings is not None
                else None
            ),
            interaction_handling=InteractionHandlingConfig.from_dict(
                data.get("interaction_handling")
            ),
            timer_store=endpoint_config("timer_store"),
            a2a_server=A2AServerConfig.from_dict(raw_a2a_server),
        )

    def __init__(
        self,
        config_file_path: Optional[Path] = None,
        nlg: Optional[EndpointConfig] = None,
        nlu: Optional[EndpointConfig] = None,
        action: Optional[EndpointConfig] = None,
        model: Optional[EndpointConfig] = None,
        tracker_store: Optional[EndpointConfig] = None,
        lock_store: Optional[EndpointConfig] = None,
        event_broker: Optional[EndpointConfig] = None,
        vector_store: Optional[EndpointConfig] = None,
        mcp_servers: Optional[List[MCPServerConfig]] = None,
        model_groups: Optional[List[Dict[str, Any]]] = None,
        privacy: Optional[Dict[str, Any]] = None,
        recordings: Optional[RecordingConfig] = None,
        interaction_handling: InteractionHandlingConfig = InteractionHandlingConfig(
            global_silence_timeout=GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE
        ),
        timer_store: Optional[EndpointConfig] = None,
        a2a_server: Optional[A2AServerConfig] = None,
    ) -> None:
        """Create an `AvailableEndpoints` object."""
        self.config_file_path = config_file_path
        self.model = model
        self.action = action
        self.nlu = nlu
        self.nlg = nlg
        self.tracker_store = tracker_store
        self.lock_store = lock_store
        self.event_broker = event_broker
        self.vector_store = vector_store
        self.mcp_servers = mcp_servers
        self.model_groups = model_groups
        self.privacy = privacy
        self.recordings = recordings
        self.interaction_handling = interaction_handling
        self.timer_store = timer_store
        self.a2a_server = a2a_server

    def to_dict(self) -> Dict[str, Any]:
        """Convert endpoint settings to a spawn-safe dictionary."""

        def endpoint_config(
            config: Optional[EndpointConfig],
        ) -> Optional[Dict[str, Any]]:
            if config is None:
                return None
            data = config.to_dict()
            data["type"] = config.type
            if isinstance(config.actions_module, ModuleType):
                data["actions_module"] = config.actions_module.__name__
            return data

        mcp_servers = None
        if self.mcp_servers:
            mcp_servers = []
            for server in self.mcp_servers:
                server_data = server.model_dump(exclude={"additional_params"})
                server_data.update(server.additional_params or {})
                mcp_servers.append(server_data)

        return {
            "nlg": endpoint_config(self.nlg),
            "nlu": endpoint_config(self.nlu),
            "action_endpoint": endpoint_config(self.action),
            "models": endpoint_config(self.model),
            "tracker_store": endpoint_config(self.tracker_store),
            "lock_store": endpoint_config(self.lock_store),
            "event_broker": endpoint_config(self.event_broker),
            "vector_store": endpoint_config(self.vector_store),
            MCP_SERVERS_KEY: mcp_servers,
            "model_groups": self.model_groups,
            "privacy": self.privacy,
            "recordings": (
                self.recordings.model_dump(mode="python") if self.recordings else None
            ),
            "interaction_handling": self.interaction_handling.to_dict(),
            "timer_store": endpoint_config(self.timer_store),
            A2A_SERVER_KEY: (
                self.a2a_server.model_dump(mode="python") if self.a2a_server else None
            ),
        }
